// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {ECDSA} from "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

import {BridgeAdapter} from "./BridgeAdapter.sol";
import {BridgeExecution, BridgeFee, BridgeQuote} from "../interfaces/IBridgeAdapter.sol";
import {IRelayDepository} from "../interfaces/IRelayDepository.sol";
import {LocalRuntime} from "../libraries/LocalRuntime.sol";

/// @title RelayAdapter
/// @notice Opens Relay Protocol v2 orders by depositing inbox assets into Relay's depository
/// @dev This source is portable to EVM chains and Tron. Relay signs the EIP-712 struct hash of an
/// order using EIP-191 personal_sign. The adapter recomputes that hash, recovers an allowlisted
/// solver, and binds all payment-critical fields before the inbox makes the deposit.
contract RelayAdapter is BridgeAdapter, Ownable {
  enum AddressEncoding {
    Evm,
    Tron,
    Solana
  }

  struct Destination {
    address tokenOut;
    string relayChainId;
    bytes outputCurrency;
    AddressEncoding addressEncoding;
    bool enabled;
  }

  struct RelayInputPayment {
    string chainId;
    bytes currency;
    uint256 amount;
    uint256 weight;
  }

  struct RelayInputRefund {
    string chainId;
    bytes recipient;
    bytes currency;
    uint256 minimumAmount;
    uint32 deadline;
    bytes extraData;
  }

  struct RelayInput {
    RelayInputPayment payment;
    RelayInputRefund[] refunds;
  }

  struct RelayOutputPayment {
    bytes recipient;
    bytes currency;
    uint256 minimumAmount;
    uint256 expectedAmount;
  }

  struct RelayOutput {
    string chainId;
    RelayOutputPayment[] payments;
    uint32 deadline;
    bytes[] calls;
    bytes extraData;
  }

  struct RelayFee {
    string recipientChainId;
    bytes recipient;
    string currencyChainId;
    bytes currency;
    uint256 amount;
  }

  struct RelayOrder {
    string version;
    string solverChainId;
    address solver;
    uint256 salt;
    RelayInput[] inputs;
    RelayOutput output;
    RelayFee[] fees;
  }

  struct RelayOrderData {
    RelayOrder order;
    bytes signature;
  }

  bytes32 private constant ORDER_TYPEHASH = keccak256(
    "Order(string version,string solverChainId,address solver,uint256 salt,Input[] inputs,Output output,Fee[] fees)Fee(string recipientChainId,bytes recipient,string currencyChainId,bytes currency,uint256 amount)Input(InputPayment payment,InputRefund[] refunds)InputPayment(string chainId,bytes currency,uint256 amount,uint256 weight)InputRefund(string chainId,bytes recipient,bytes currency,uint256 minimumAmount,uint32 deadline,bytes extraData)Output(string chainId,OutputPayment[] payments,uint32 deadline,bytes[] calls,bytes extraData)OutputPayment(bytes recipient,bytes currency,uint256 minimumAmount,uint256 expectedAmount)"
  );
  bytes32 private constant INPUT_TYPEHASH = keccak256(
    "Input(InputPayment payment,InputRefund[] refunds)InputPayment(string chainId,bytes currency,uint256 amount,uint256 weight)InputRefund(string chainId,bytes recipient,bytes currency,uint256 minimumAmount,uint32 deadline,bytes extraData)"
  );
  bytes32 private constant INPUT_PAYMENT_TYPEHASH =
    keccak256("InputPayment(string chainId,bytes currency,uint256 amount,uint256 weight)");
  bytes32 private constant INPUT_REFUND_TYPEHASH = keccak256(
    "InputRefund(string chainId,bytes recipient,bytes currency,uint256 minimumAmount,uint32 deadline,bytes extraData)"
  );
  bytes32 private constant OUTPUT_TYPEHASH = keccak256(
    "Output(string chainId,OutputPayment[] payments,uint32 deadline,bytes[] calls,bytes extraData)OutputPayment(bytes recipient,bytes currency,uint256 minimumAmount,uint256 expectedAmount)"
  );
  bytes32 private constant OUTPUT_PAYMENT_TYPEHASH =
    keccak256("OutputPayment(bytes recipient,bytes currency,uint256 minimumAmount,uint256 expectedAmount)");
  bytes32 private constant FEE_TYPEHASH =
    keccak256("Fee(string recipientChainId,bytes recipient,string currencyChainId,bytes currency,uint256 amount)");
  bytes32 private constant VERSION_HASH = keccak256("v1");

  IRelayDepository public immutable RELAY_DEPOSITORY;
  string public originRelayChainId;

  /// @dev Resolved once, at construction, from the VM's own CREATE2 behaviour — the same detection
  /// the router uses, so the adapter's canonical address encoding cannot disagree with the runtime
  /// the router derived its inbox addresses under.
  bool private immutable IS_TRON_RUNTIME;

  mapping(address solver => bool approved) public approvedSolvers;
  mapping(address tokenIn => mapping(uint256 dstChainId => Destination destination)) public destinations;

  /// @dev One-shot ticket: the same solver-signed order can never deposit twice through the same
  /// router. Set before the depository deposit, so re-executing an order reverts before any second
  /// debit. Keyed by the calling router (the `IInboxCallback` that owns the inbox call path) because
  /// `execute` is permissionless: a global marker would let anyone replay a mempool order through
  /// their own no-op callback and burn it before the real route lands.
  mapping(address router => mapping(bytes32 orderId => bool consumed)) public consumedOrders;

  event SolverSet(address indexed _solver, bool _approved);
  event DestinationSet(
    address indexed _tokenIn,
    uint256 indexed _dstChainId,
    address indexed _tokenOut,
    string _relayChainId,
    bytes _outputCurrency,
    AddressEncoding _addressEncoding
  );
  event DestinationCleared(address indexed _tokenIn, uint256 indexed _dstChainId);
  event RelayOrderOpened(
    bytes32 indexed _orderId,
    address indexed _inbox,
    address indexed _solver,
    address _tokenIn,
    address _tokenOut,
    uint256 _amountIn,
    uint256 _amountOut,
    uint256 _dstChainId,
    bytes32 _recipient
  );

  error ZeroAddress();
  error InvalidOriginChainId();
  error InvalidRelayChainId();
  error InvalidCurrency();
  error InvalidRecipient();
  error InvalidAmount();
  error InvalidMinAmountOut();
  error UnsupportedDestination(address _tokenIn, uint256 _dstChainId);
  error InvalidTokenOut(address _expected, address _actual);
  error InvalidOrderShape();
  error InvalidOrderVersion();
  error InvalidOrderInput();
  error InvalidOrderRefund();
  error InvalidOrderOutput();
  error OrderExpired(uint32 _deadline);
  error OrderAlreadyConsumed(bytes32 _orderId);
  error UnapprovedSolver(address _solver);
  error InvalidSolverSignature(address _expected, address _recovered);

  constructor(address _relayDepository, address _owner, string memory _originRelayChainId) Ownable(_owner) {
    if (_relayDepository == address(0) || _owner == address(0)) {
      revert ZeroAddress();
    }
    if (bytes(_originRelayChainId).length == 0) {
      revert InvalidOriginChainId();
    }

    RELAY_DEPOSITORY = IRelayDepository(_relayDepository);
    originRelayChainId = _originRelayChainId;
    IS_TRON_RUNTIME = _detectLocalRuntime();
  }

  /// @notice True when this deployment resolved itself to the TVM at construction.
  function localRuntimeIsTron() external view returns (bool) {
    return IS_TRON_RUNTIME;
  }

  /// @dev See `Inboxes._detectLocalRuntime`: `virtual` purely as a test seam.
  function _detectLocalRuntime() internal virtual returns (bool) {
    return LocalRuntime.detect();
  }

  function setSolver(address _solver, bool _approved) external onlyOwner {
    if (_solver == address(0)) {
      revert ZeroAddress();
    }
    approvedSolvers[_solver] = _approved;
    emit SolverSet(_solver, _approved);
  }

  /// @notice Registers the Relay-specific identifiers for a Trails bridge route.
  /// @param _tokenOut Trails' accounting token for the remote asset. For non-EVM assets this may
  /// be a 20-byte alias; `_outputCurrency` always carries Relay's full canonical token bytes.
  function setDestination(
    address _tokenIn,
    uint256 _dstChainId,
    address _tokenOut,
    string calldata _relayChainId,
    bytes calldata _outputCurrency,
    AddressEncoding _addressEncoding
  ) external onlyOwner {
    if (_dstChainId == 0) {
      revert UnsupportedDestination(_tokenIn, _dstChainId);
    }
    if (bytes(_relayChainId).length == 0) {
      revert InvalidRelayChainId();
    }
    _requireCanonicalAddress(_outputCurrency, _addressEncoding);

    destinations[_tokenIn][_dstChainId] = Destination({
      tokenOut: _tokenOut,
      relayChainId: _relayChainId,
      outputCurrency: _outputCurrency,
      addressEncoding: _addressEncoding,
      enabled: true
    });
    _setBridgeRoute(_tokenIn, _tokenOut, _dstChainId);

    emit DestinationSet(_tokenIn, _dstChainId, _tokenOut, _relayChainId, _outputCurrency, _addressEncoding);
  }

  function clearDestination(address _tokenIn, uint256 _dstChainId) external onlyOwner {
    delete destinations[_tokenIn][_dstChainId];
    _clearBridgeRoute(_tokenIn, _dstChainId);
    emit DestinationCleared(_tokenIn, _dstChainId);
  }

  function quote(
    address _tokenIn,
    address _tokenOut,
    uint256 _amountIn,
    uint256 _minAmountOut,
    uint256 _dstChainId,
    bytes32 _recipient,
    bytes calldata _adapterCalldata
  ) external view override returns (BridgeQuote memory _quote) {
    if (_amountIn == 0) {
      revert InvalidAmount();
    }
    Destination storage destination = _validatedDestination(_tokenIn, _tokenOut, _dstChainId);
    RelayOrderData memory data = abi.decode(_adapterCalldata, (RelayOrderData));
    (bytes32 relayOrderId, uint256 amountOut) =
      _validateOrder(data, destination, address(0), _tokenIn, _amountIn, _minAmountOut, _recipient, false);
    // Quoting is done by the router (`msg.sender`), the same key `execute` consumes under, so a
    // spent order fails here instead of only at execution.
    _requireOrderNotConsumed(relayOrderId);
    return _bridgeQuote(_amountIn, amountOut);
  }

  function execute(
    address _inbox,
    address _tokenIn,
    address _tokenOut,
    uint256 _amountIn,
    uint256 _minAmountOut,
    uint256 _dstChainId,
    bytes32 _recipient,
    bytes calldata _adapterCalldata
  ) external override returns (BridgeExecution memory _execution) {
    Destination storage destination = _validatedDestination(_tokenIn, _tokenOut, _dstChainId);
    uint256 amountIn = _resolveAmountIn(_amountIn, _inboxAssetBalance(_inbox, _tokenIn));
    if (amountIn == 0) {
      revert InvalidAmount();
    }

    RelayOrderData memory data = abi.decode(_adapterCalldata, (RelayOrderData));
    (bytes32 relayOrderId, uint256 amountOut) =
      _validateOrder(data, destination, _inbox, _tokenIn, amountIn, _minAmountOut, _recipient, true);
    // The signed order is a one-shot ticket: a replayed execution would debit the inbox a second
    // time for a payout Relay settles once. Mark it consumed before the deposit so the second
    // attempt reverts here instead of losing funds. The marker is scoped to `msg.sender`, the
    // router whose callback moves the inbox funds, so a third party cannot consume it for them.
    _requireOrderNotConsumed(relayOrderId);
    consumedOrders[msg.sender][relayOrderId] = true;
    _execution = BridgeExecution({operationId: relayOrderId, quote: _bridgeQuote(amountIn, amountOut)});

    if (_tokenIn == address(0)) {
      _executeInboxTransaction(
        _inbox,
        address(RELAY_DEPOSITORY),
        amountIn,
        abi.encodeCall(IRelayDepository.depositNative, (_inbox, relayOrderId))
      );
    } else {
      _setInboxTokenApproval(_inbox, _tokenIn, address(RELAY_DEPOSITORY), amountIn);
      _executeInboxTransaction(
        _inbox,
        address(RELAY_DEPOSITORY),
        0,
        abi.encodeCall(IRelayDepository.depositErc20, (_inbox, _tokenIn, amountIn, relayOrderId))
      );
      _setInboxTokenApproval(_inbox, _tokenIn, address(RELAY_DEPOSITORY), 0);
    }

    emit RelayOrderOpened(
      relayOrderId, _inbox, data.order.solver, _tokenIn, _tokenOut, amountIn, amountOut, _dstChainId, _recipient
    );
  }

  /// @notice Canonical Relay Protocol v2 order identifier (EIP-712 hashStruct, without a domain).
  function getOrderId(RelayOrder calldata _order) external pure returns (bytes32) {
    RelayOrder memory order = _order;
    return _hashOrder(order);
  }

  function _validatedDestination(address _tokenIn, address _tokenOut, uint256 _dstChainId)
    private
    view
    returns (Destination storage destination)
  {
    destination = destinations[_tokenIn][_dstChainId];
    if (!destination.enabled) {
      revert UnsupportedDestination(_tokenIn, _dstChainId);
    }
    if (destination.tokenOut != _tokenOut) {
      revert InvalidTokenOut(destination.tokenOut, _tokenOut);
    }
  }

  function _validateOrder(
    RelayOrderData memory _data,
    Destination storage _destination,
    address _inbox,
    address _tokenIn,
    uint256 _amountIn,
    uint256 _minAmountOut,
    bytes32 _recipient,
    bool _validateRefundRecipient
  ) private view returns (bytes32 orderId_, uint256 amountOut) {
    RelayOrder memory order = _data.order;
    if (keccak256(bytes(order.version)) != VERSION_HASH) {
      revert InvalidOrderVersion();
    }
    if (
      order.inputs.length != 1 || order.inputs[0].refunds.length == 0 || order.output.payments.length != 1
        || order.output.calls.length != 0
    ) {
      revert InvalidOrderShape();
    }

    RelayInput memory input = order.inputs[0];
    bytes memory localCurrency = _localCurrency(_tokenIn);
    if (
      keccak256(bytes(input.payment.chainId)) != keccak256(bytes(originRelayChainId))
        || keccak256(input.payment.currency) != keccak256(localCurrency) || input.payment.amount != _amountIn
        || input.payment.weight != 1
    ) {
      revert InvalidOrderInput();
    }

    RelayOutputPayment memory payment = order.output.payments[0];
    bytes memory outputRecipient = _encodeRecipient(_recipient, _destination.addressEncoding);
    bytes memory refundRecipient = _validateRefundRecipient ? _localRecipient(_inbox) : bytes("");
    bool hasOriginRefund;
    for (uint256 i = 0; i < input.refunds.length; i++) {
      RelayInputRefund memory refund = input.refunds[i];
      if (keccak256(bytes(refund.chainId)) == keccak256(bytes(originRelayChainId))) {
        if (
          keccak256(refund.currency) != keccak256(localCurrency)
            || (_validateRefundRecipient && keccak256(refund.recipient) != keccak256(refundRecipient))
        ) {
          revert InvalidOrderRefund();
        }
        hasOriginRefund = true;
      } else if (keccak256(bytes(refund.chainId)) == keccak256(bytes(_destination.relayChainId))) {
        if (
          keccak256(refund.currency) != keccak256(_destination.outputCurrency)
            || keccak256(refund.recipient) != keccak256(outputRecipient)
        ) {
          revert InvalidOrderRefund();
        }
      } else {
        revert InvalidOrderRefund();
      }
    }
    if (!hasOriginRefund) {
      revert InvalidOrderRefund();
    }

    if (
      keccak256(bytes(order.output.chainId)) != keccak256(bytes(_destination.relayChainId))
        || keccak256(payment.currency) != keccak256(_destination.outputCurrency)
        || keccak256(payment.recipient) != keccak256(outputRecipient) || payment.minimumAmount == 0
        || payment.minimumAmount < _minAmountOut || payment.expectedAmount < payment.minimumAmount
    ) {
      revert InvalidOrderOutput();
    }
    if (order.output.deadline < block.timestamp) {
      revert OrderExpired(order.output.deadline);
    }

    orderId_ = _hashOrder(order);
    bytes32 digest = keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", orderId_));
    address recovered = ECDSA.recover(digest, _data.signature);
    if (recovered != order.solver) {
      revert InvalidSolverSignature(order.solver, recovered);
    }
    if (!approvedSolvers[recovered]) {
      revert UnapprovedSolver(recovered);
    }

    return (orderId_, payment.minimumAmount);
  }

  function _requireOrderNotConsumed(bytes32 _orderId) private view {
    if (consumedOrders[msg.sender][_orderId]) {
      revert OrderAlreadyConsumed(_orderId);
    }
  }

  function _bridgeQuote(uint256 _amountIn, uint256 _amountOut) private pure returns (BridgeQuote memory _quote) {
    if (_amountOut == 0) {
      revert InvalidMinAmountOut();
    }
    BridgeFee[] memory fees = new BridgeFee[](0);
    return BridgeQuote({amountIn: _amountIn, amountOut: _amountOut, fees: fees});
  }

  function _localCurrency(address _token) private view returns (bytes memory) {
    if (IS_TRON_RUNTIME) {
      return abi.encodePacked(bytes1(0x41), _token);
    }
    return abi.encodePacked(_token);
  }

  function _localRecipient(address _recipient) private view returns (bytes memory) {
    if (IS_TRON_RUNTIME) {
      return abi.encodePacked(bytes1(0x41), _recipient);
    }
    return abi.encodePacked(_recipient);
  }

  function _encodeRecipient(bytes32 _recipient, AddressEncoding _encoding) private pure returns (bytes memory) {
    if (_encoding == AddressEncoding.Solana) {
      return abi.encodePacked(_recipient);
    }
    if (uint256(_recipient) > type(uint160).max) {
      revert InvalidRecipient();
    }
    address recipient = address(uint160(uint256(_recipient)));
    if (_encoding == AddressEncoding.Tron) {
      return abi.encodePacked(bytes1(0x41), recipient);
    }
    return abi.encodePacked(recipient);
  }

  function _requireCanonicalAddress(bytes calldata _value, AddressEncoding _encoding) private pure {
    if (_encoding == AddressEncoding.Evm) {
      if (_value.length != 20) revert InvalidCurrency();
      return;
    }
    if (_encoding == AddressEncoding.Tron) {
      if (_value.length != 21 || _value[0] != 0x41) revert InvalidCurrency();
      return;
    }
    if (_value.length != 32) revert InvalidCurrency();
  }

  function _hashOrder(RelayOrder memory _order) private pure returns (bytes32) {
    bytes32[] memory inputHashes = new bytes32[](_order.inputs.length);
    for (uint256 i = 0; i < _order.inputs.length; i++) {
      inputHashes[i] = _hashInput(_order.inputs[i]);
    }

    bytes32[] memory feeHashes = new bytes32[](_order.fees.length);
    for (uint256 i = 0; i < _order.fees.length; i++) {
      feeHashes[i] = _hashFee(_order.fees[i]);
    }

    return keccak256(
      abi.encode(
        ORDER_TYPEHASH,
        keccak256(bytes(_order.version)),
        keccak256(bytes(_order.solverChainId)),
        _order.solver,
        _order.salt,
        keccak256(abi.encodePacked(inputHashes)),
        _hashOutput(_order.output),
        keccak256(abi.encodePacked(feeHashes))
      )
    );
  }

  function _hashInput(RelayInput memory _input) private pure returns (bytes32) {
    bytes32[] memory refundHashes = new bytes32[](_input.refunds.length);
    for (uint256 i = 0; i < _input.refunds.length; i++) {
      RelayInputRefund memory refund = _input.refunds[i];
      refundHashes[i] = keccak256(
        abi.encode(
          INPUT_REFUND_TYPEHASH,
          keccak256(bytes(refund.chainId)),
          keccak256(refund.recipient),
          keccak256(refund.currency),
          refund.minimumAmount,
          refund.deadline,
          keccak256(refund.extraData)
        )
      );
    }

    RelayInputPayment memory payment = _input.payment;
    bytes32 paymentHash = keccak256(
      abi.encode(
        INPUT_PAYMENT_TYPEHASH,
        keccak256(bytes(payment.chainId)),
        keccak256(payment.currency),
        payment.amount,
        payment.weight
      )
    );
    return keccak256(abi.encode(INPUT_TYPEHASH, paymentHash, keccak256(abi.encodePacked(refundHashes))));
  }

  function _hashOutput(RelayOutput memory _output) private pure returns (bytes32) {
    bytes32[] memory paymentHashes = new bytes32[](_output.payments.length);
    for (uint256 i = 0; i < _output.payments.length; i++) {
      RelayOutputPayment memory payment = _output.payments[i];
      paymentHashes[i] = keccak256(
        abi.encode(
          OUTPUT_PAYMENT_TYPEHASH,
          keccak256(payment.recipient),
          keccak256(payment.currency),
          payment.minimumAmount,
          payment.expectedAmount
        )
      );
    }

    bytes32[] memory callHashes = new bytes32[](_output.calls.length);
    for (uint256 i = 0; i < _output.calls.length; i++) {
      callHashes[i] = keccak256(_output.calls[i]);
    }
    return keccak256(
      abi.encode(
        OUTPUT_TYPEHASH,
        keccak256(bytes(_output.chainId)),
        keccak256(abi.encodePacked(paymentHashes)),
        _output.deadline,
        keccak256(abi.encodePacked(callHashes)),
        keccak256(_output.extraData)
      )
    );
  }

  function _hashFee(RelayFee memory _fee) private pure returns (bytes32) {
    return keccak256(
      abi.encode(
        FEE_TYPEHASH,
        keccak256(bytes(_fee.recipientChainId)),
        keccak256(_fee.recipient),
        keccak256(bytes(_fee.currencyChainId)),
        keccak256(_fee.currency),
        _fee.amount
      )
    );
  }
}

