// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {InboxAddress} from "./InboxAddress.sol";

/// @title LocalRuntime
/// @notice Self-verifying detection of the runtime a deployment is executing on.
/// @dev Trails needs to know whether it is running on the TVM or on an EVM chain, because the two
/// derive CREATE2 addresses differently (Tron replaces the `0xff` prefix with `0x41`). That single
/// answer also selects which owner slot authorizes an inbox and which canonical address encoding
/// bridge adapters emit.
///
/// The answer is derived from the VM's own CREATE2 behaviour instead of being asserted: deploy a
/// throwaway probe with a known salt and init code, then check which of the two address formulas
/// reproduces the address the VM actually used. A chain-id whitelist goes stale (and silently takes
/// the wrong branch on any Tron network missing from it); a constructor argument can be passed
/// wrong. This can do neither, and a VM matching *neither* formula fails the deployment instead of
/// mis-deriving every counterfactual inbox address for the lifetime of the contract.
///
/// Callers must resolve this ONCE, at construction, into an `immutable`. The answer feeds inbox
/// address derivation, so changing it later would re-derive every counterfactual address and orphan
/// funds already sent to previously-published ones.
library LocalRuntime {
  /// @dev Probe init code returning a single `STOP` byte as its runtime:
  ///
  ///   60 01    push1 0x01     // [runtime_size]
  ///   80       dup1           // [runtime_size, runtime_size]
  ///   60 0b    push1 0x0b     // [runtime_offset, runtime_size, runtime_size]
  ///   60 00    push1 0x00     // [0, runtime_offset, runtime_size, runtime_size]
  ///   39       codecopy       // [runtime_size]
  ///   60 00    push1 0x00     // [0, runtime_size]
  ///   f3       return         // return(0, 1)
  ///   00       <runtime>      // STOP
  ///
  /// Deliberately avoids `PUSH0` so the probe itself does not depend on the Shanghai opcode set.
  bytes internal constant PROBE_CREATION_CODE = hex"600180600b6000396000f300";

  /// @dev Salt for the probe. Domain separated from any configuration root, so probing can never
  /// consume an address an inbox would otherwise occupy.
  ///
  /// The probe address is not squattable: it is a CREATE2 address naming the probing contract as
  /// deployer, so nothing but that contract can ever deploy there. No fallback salt is needed — and
  /// none would help, because an address collision consumes all gas forwarded to the failed create.
  bytes32 internal constant PROBE_SALT = keccak256("TrailsPdas.LocalRuntime.probe.v1");

  error UnknownLocalRuntime(address _probe);
  error ProbeDeploymentFailed();

  /// @notice Decides which CREATE2 formula produced `_probe`.
  /// @dev Split out from the deployment so both branches are unit testable on a single VM.
  /// @return _isTron True when the address matches Tron's `0x41`-prefixed derivation.
  function resolve(address _deployer, bytes32 _salt, bytes32 _initCodeHash, address _probe)
    internal
    pure
    returns (bool _isTron)
  {
    if (_probe == InboxAddress.computeTron(_deployer, _salt, _initCodeHash)) {
      return true;
    }
    if (_probe == InboxAddress.computeEvm(_deployer, _salt, _initCodeHash)) {
      return false;
    }

    // Neither formula matched: this VM derives CREATE2 addresses in a way Trails cannot predict, so
    // no counterfactual inbox address it publishes would be reachable. Refuse to deploy.
    revert UnknownLocalRuntime(_probe);
  }

  /// @notice Deploys the probe and returns whether this VM uses Tron's CREATE2 derivation.
  /// @dev `internal`, so it is inlined and `address(this)` is the calling contract — the same
  /// deployer that will later create inboxes.
  function detect() internal returns (bool _isTron) {
    bytes memory creationCode = PROBE_CREATION_CODE;
    // `PROBE_SALT` is a constant expression, not a literal, so inline assembly cannot name it.
    bytes32 salt = PROBE_SALT;
    address probe;
    assembly ("memory-safe") {
      probe := create2(0, add(creationCode, 0x20), mload(creationCode), salt)
    }

    // Unreachable for a first-time deployment (see `PROBE_SALT`). Refuse rather than guess.
    if (probe == address(0)) {
      revert ProbeDeploymentFailed();
    }

    return resolve(address(this), PROBE_SALT, keccak256(creationCode), probe);
  }
}

